///          ..
/// # ; true
///     }
/// }
///
/// impl Eq for Bad {}
///
/// impl Hash for Bad {
///     fn hash<H: Hasher>(&self, h: &mut H) {
///         ..
/// # ;
///     }
/// }
///
/// fn main() {
///     let _: HashSet<Bad> = HashSet::new();
/// }
/// ```
